def process(floridaFraudMsa, metroFraudOther2024) -> pd.DataFrame:
    import pandas as pd

    def norm(s):
        return str(s).strip().lower()

    # Identify likely columns
    def find_col(df, candidates):
        cols = {norm(c): c for c in df.columns}
        for cand in candidates:
            for k, v in cols.items():
                if cand in k:
                    return v
        return None

    # For metro file
    metroAreaCol = find_col(metroFraudOther2024, ["metropolitan", "msa", "metro", "area"])
    metroCountCol = find_col(metroFraudOther2024, ["report", "count", "reports"])

    # For florida state-msa fraud file
    flMsaCol = find_col(floridaFraudMsa, ["metropolitan", "msa", "metro", "area"])
    flCountCol = find_col(floridaFraudMsa, ["report", "count", "reports"])

    target = "miami-fort lauderdale-west palm beach"

    def filter_target(df, area_col):
        ser = df[area_col].astype(str).str.lower().str.strip()
        # allow minor punctuation differences
        return df[ser.str.contains("miami") & ser.str.contains("fort") & ser.str.contains("lauderdale") & ser.str.contains("west") & ser.str.contains("palm") & ser.str.contains("beach")]

    metro_row = filter_target(metroFraudOther2024, metroAreaCol) if metroAreaCol else metroFraudOther2024.iloc[0:0]
    fl_row = filter_target(floridaFraudMsa, flMsaCol) if flMsaCol else floridaFraudMsa.iloc[0:0]

    # Coerce counts to numeric (may have commas)
    def get_count(df, col):
        if df.shape[0] == 0 or col is None:
            return None
        val = df.iloc[0][col]
        return pd.to_numeric(str(val).replace(",", ""), errors="coerce")

    metro_count = get_count(metro_row, metroCountCol)
    fl_count = get_count(fl_row, flCountCol)

    consistent = bool((metro_count is not None) and (fl_count is not None) and pd.notna(metro_count) and pd.notna(fl_count) and float(metro_count) == float(fl_count))

    return pd.DataFrame([{
        "metro_count": metro_count,
        "fl_count": fl_count,
        "consistent": consistent,
        "metroAreaCol": metroAreaCol,
        "metroCountCol": metroCountCol,
        "flMsaCol": flMsaCol,
        "flCountCol": flCountCol,
        "metro_matches": int(metro_row.shape[0]) if metroAreaCol else 0,
        "fl_matches": int(fl_row.shape[0]) if flMsaCol else 0
    }])

