def process(metroFraudOther2024) -> pd.DataFrame:
    import pandas as pd

    df = metroFraudOther2024.copy()

    # The file is loaded with a top title row and then the real header at row index 1.
    # If we detect the second row contains the expected column labels, use it as header.
    if len(df) >= 3:
        potential_header = df.iloc[1].tolist()
        header_str = ["" if pd.isna(x) else str(x).strip() for x in potential_header]
        if ("Metropolitan Area" in header_str) and ("# of Reports" in header_str):
            df2 = df.iloc[2:].copy()
            df2.columns = header_str
            df = df2

    # Drop fully empty rows
    df = df.dropna(how='all')

    # Standardize column names
    rename = {}
    for c in df.columns:
        cs = str(c).strip()
        if cs.lower() == 'metropolitan area':
            rename[c] = 'metropolitan_area'
        elif cs.lower() == '# of reports':
            rename[c] = 'report_count'
        elif cs.lower() == 'reports per 100k population':
            rename[c] = 'reports_per_100k'
        elif cs.lower() == 'rank':
            rename[c] = 'rank'
    df = df.rename(columns=rename)

    # Keep only expected columns if present
    cols = [c for c in ['rank','metropolitan_area','reports_per_100k','report_count'] if c in df.columns]
    if cols:
        df = df[cols]

    # Parse numerics
    if 'report_count' in df.columns:
        df['report_count'] = (
            df['report_count'].astype(str)
            .str.replace(',', '', regex=False)
            .str.extract(r'([0-9]+(?:\.[0-9]+)?)', expand=False)
        )
        df['report_count'] = pd.to_numeric(df['report_count'], errors='coerce')
    if 'reports_per_100k' in df.columns:
        df['reports_per_100k'] = (
            df['reports_per_100k'].astype(str)
            .str.extract(r'([0-9]+(?:\.[0-9]+)?)', expand=False)
        )
        df['reports_per_100k'] = pd.to_numeric(df['reports_per_100k'], errors='coerce')
    if 'rank' in df.columns:
        df['rank'] = pd.to_numeric(df['rank'], errors='coerce')

    return df
